/**
 * MamamyTowerGame — Claw-drop stacking: stack 10 Mamamy products in 30 seconds.
 *
 * Flow: INTRO → tap → AIMING (claw swings holding an item, tap to drop)
 *       → DROPPING (falls straight down: x + rotation frozen) → landed:
 *           upper item overlaps the one below by >= minOverlap → freeze, +1 floor
 *           otherwise → TOPPLING (rotation unlocked, falls) → RESULT (lose)
 *       → winFloors reached → RESULT (win) · timer hits 0 → RESULT (lose)
 *       → tap → retry
 *
 * Items come from a pre-built pool (Items/Item..Item (11)) so they keep their
 * scene-load draw order (above the claw, below HUD/overlays).
 * Coordinates are screen pixels (720x1280, origin at center); physics uses 32 px/m.
 */
@component()
export class MamamyTowerGame extends APJS.BasicScriptComponent {
  @header("Theme & Assets")
  @serializeProperty @tooltip('Wide, easy products (first item is the first entry)') easyTextures: APJS.Texture[] = [];
  @serializeProperty @tooltip('Bottles / pouches with narrow tops') mediumTextures: APJS.Texture[] = [];
  @serializeProperty @tooltip('Hardest products (tall and narrow)') hardTextures: APJS.Texture[] = [];

  @header("Gameplay Tuning")
  @serializeProperty @tooltip('Round length (s)') @spinBox(10, 120, 1) timeLimitSec: number = 30;
  @serializeProperty @tooltip('Floors needed to win') @spinBox(2, 11, 1) winFloors: number = 10;
  @serializeProperty @tooltip('Min overlap of the upper item on the one below') @slider(0.05, 0.9, 0.05) minOverlap: number = 0.3;
  @serializeProperty @tooltip('Claw speed (px/s)') @slider(60, 500, 10) swingSpeed: number = 160;
  @serializeProperty @tooltip('Extra claw speed per floor (px/s)') @slider(0, 40, 1) swingSpeedPerFloor: number = 6;
  @serializeProperty @tooltip('Max claw speed (px/s)') @slider(60, 700, 10) swingSpeedMax: number = 300;
  @serializeProperty @tooltip('Claw swing half-range (px)') @slider(50, 300, 5) swingRange: number = 190;
  @serializeProperty @tooltip('Product size vs source image') @slider(0.3, 1, 0.01) itemScale: number = 0.53;
  @serializeProperty @tooltip('Fall speed multiplier') @slider(1, 12, 0.5) fallGravityScale: number = 4;
  @serializeProperty @tooltip('Floor from which bottles/pouch appear') @spinBox(1, 20, 1) mediumFromFloor: number = 4;
  @serializeProperty @tooltip('Floor from which the brush set appears') @spinBox(1, 20, 1) hardFromFloor: number = 7;

  @header("Advanced — Scene Wiring")
  @serializeProperty itemPool: APJS.SceneObject[] = [];
  @serializeProperty claw: APJS.SceneObject;
  @serializeProperty ground: APJS.SceneObject;
  @serializeProperty nextThumb: APJS.SceneObject;
  @serializeProperty scoreText: APJS.SceneObject;
  @serializeProperty timerText: APJS.SceneObject;
  @serializeProperty popupText: APJS.SceneObject;
  @serializeProperty introOverlay: APJS.SceneObject;
  @serializeProperty resultOverlay: APJS.SceneObject;
  @serializeProperty resultTitle: APJS.SceneObject;
  @serializeProperty resultReason: APJS.SceneObject;
  @serializeProperty resultScore: APJS.SceneObject;

  // Layout invariants measured from the built scene.
  private readonly PPU: number = 32;
  private readonly swingCenterX: number = -30;
  private readonly clawTipSpan: number = 211;   // px between the red tips at scale 1
  private readonly heldTopOffset: number = 84;  // item top sits 42% down the 201px claw
  private readonly keepTopY: number = -150;     // tower top is scrolled to stay below this
  private readonly settleSpeed: number = 0.25;  // m/s
  private readonly settleFrames: number = 10;
  private readonly toppleLoseSec: number = 1.2;
  private readonly perfectPx: number = 12;

  private inited: boolean = false;
  private state: string = "INTRO";
  private items: TowerItem[] = [];
  private tower: TowerItem[] = [];
  private held: TowerItem | undefined;
  private falling: TowerItem | undefined;
  private nextTex: APJS.Texture | undefined;
  private prevPickTier: string = "";
  private poolIndex: number = 0;

  private clawSt!: APJS.ScreenTransform;
  private clawBaseY: number = 0;
  private clawX: number = 0;
  private clawDir: number = 1;
  private clawScale: number = 1;
  private groundSt!: APJS.ScreenTransform;
  private groundRb!: APJS.RigidBody2D;
  private groundBaseY: number = 0;
  private groundTopY: number = -400;
  private nextImg!: APJS.Image;
  private popupSt!: APJS.ScreenTransform;

  private score: number = 0;
  private timeLeft: number = 0;
  private heldAnim: number = 0;
  private lowFrames: number = 0;
  private toppleTime: number = 0;
  private resultTime: number = 0;
  private popupTime: number = 0;
  private popupY: number = 0;
  private towerTop: number = 0;

  onStart(): void {
    APJS.EventManager.getGlobalEmitter().on(APJS.EventType.Touch, this.onTouch, this);
    APJS.EventManager.getGlobalEmitter().on(APJS.EventType.RecordStart, this.onRecordStart, this);
  }

  onDestroy(): void {
    APJS.EventManager.getGlobalEmitter().off(APJS.EventType.Touch, this.onTouch, this);
    APJS.EventManager.getGlobalEmitter().off(APJS.EventType.RecordStart, this.onRecordStart, this);
  }

  // Serialized refs are only populated after onStart, so wire everything lazily.
  private initOnce(): boolean {
    if (this.inited) return true;
    if (!this.claw || !this.ground || this.itemPool.length === 0 || this.easyTextures.length === 0) return false;
    this.clawSt = this.claw.getComponent("ScreenTransform") as APJS.ScreenTransform;
    this.clawBaseY = this.clawSt.anchoredPosition.y;
    this.groundSt = this.ground.getComponent("ScreenTransform") as APJS.ScreenTransform;
    this.groundRb = this.ground.getComponent("RigidBody2D") as APJS.RigidBody2D;
    this.groundBaseY = this.groundSt.anchoredPosition.y;
    const gcol = this.ground.getComponent("BoxCollider2D") as APJS.BoxCollider2D;
    this.groundTopY = this.groundBaseY + (gcol.offset.y + gcol.size.y * 0.5) * this.PPU;
    if (this.nextThumb) this.nextImg = this.nextThumb.getComponent("Image") as APJS.Image;
    if (this.popupText) this.popupSt = this.popupText.getComponent("ScreenTransform") as APJS.ScreenTransform;
    for (const obj of this.itemPool) {
      if (!obj) continue;
      const it = new TowerItem();
      it.obj = obj;
      it.st = obj.getComponent("ScreenTransform") as APJS.ScreenTransform;
      it.rb = obj.getComponent("RigidBody2D") as APJS.RigidBody2D;
      it.col = obj.getComponent("BoxCollider2D") as APJS.BoxCollider2D;
      it.img = obj.getComponent("Image") as APJS.Image;
      this.items.push(it);
    }
    this.inited = true;
    this.resetGame();
    return true;
  }

  onUpdate(dt: number): void {
    if (!this.initOnce()) return;
    this.updateClaw(dt);
    this.updatePopup(dt);
    if (this.state === "RESULT") this.resultTime += dt;

    if (this.state === "AIMING" || this.state === "DROPPING" || this.state === "TOPPLING") {
      this.timeLeft -= dt;
      if (this.timeLeft <= 0) {
        this.timeLeft = 0;
        this.updateHud();
        this.showResult(false, "Hết giờ rồi!");
        return;
      }
      this.updateHud();
    }

    if (this.state === "AIMING") {
      this.updateHeld(dt);
      this.updateScroll(dt);
    } else if (this.state === "DROPPING") {
      this.updateFalling();
    } else if (this.state === "TOPPLING") {
      this.toppleTime += dt;
      if (this.toppleTime >= this.toppleLoseSec) this.showResult(false, "Lệch quá, tháp đổ rồi!");
    }
  }

  // ---------- Input / lifecycle ----------
  private onTouch(event: APJS.IEvent): void {
    const t = event.args[0] as APJS.TouchData;
    if (t.phase !== APJS.TouchPhase.Began || !this.inited) return;
    if (this.state === "INTRO") this.startGame();
    else if (this.state === "AIMING") this.drop();
    else if (this.state === "RESULT" && this.resultTime > 0.8) { this.resetGame(); this.startGame(); }
  }

  private onRecordStart(): void {
    if (this.inited) this.resetGame();
  }

  private resetGame(): void {
    for (const it of this.items) this.parkItem(it);
    this.tower = [];
    this.held = undefined;
    this.falling = undefined;
    this.poolIndex = 0;
    this.score = 0;
    this.timeLeft = this.timeLimitSec;
    this.towerTop = this.groundTopY;
    this.prevPickTier = "";
    this.clawX = this.swingCenterX;
    this.clawDir = 1;
    this.setGroundY(this.groundBaseY);
    this.nextTex = this.pickTexture(0);
    this.setNextThumb();
    this.hidePopup();
    if (this.resultOverlay) this.resultOverlay.setEnabledInHierarchy(false);
    if (this.introOverlay) this.introOverlay.setEnabledInHierarchy(true);
    this.updateHud();
    this.state = "INTRO";
  }

  private startGame(): void {
    if (this.introOverlay) this.introOverlay.setEnabledInHierarchy(false);
    this.timeLeft = this.timeLimitSec;
    this.spawnHeld();
    this.state = "AIMING";
  }

  // ---------- Claw ----------
  private currentSwingSpeed(): number {
    return Math.min(this.swingSpeed + this.score * this.swingSpeedPerFloor, this.swingSpeedMax);
  }

  private updateClaw(dt: number): void {
    if (this.state !== "RESULT") {
      this.clawX += this.clawDir * this.currentSwingSpeed() * dt;
      const lo = this.swingCenterX - this.swingRange, hi = this.swingCenterX + this.swingRange;
      if (this.clawX > hi) { this.clawX = 2 * hi - this.clawX; this.clawDir = -1; }
      if (this.clawX < lo) { this.clawX = 2 * lo - this.clawX; this.clawDir = 1; }
    }
    // Arms grip the held item's width; open wide when empty.
    const target = this.held ? clamp((this.held.w + 16) / this.clawTipSpan, 0.72, 1.4) : 1.15;
    this.clawScale += (target - this.clawScale) * Math.min(1, dt * 10);
    this.clawSt.anchoredPosition = new APJS.Vector2f(this.clawX, this.clawBaseY);
    this.clawSt.scale = new APJS.Vector2f(this.clawScale, 1);
  }

  // ---------- Items ----------
  private pickTexture(floor: number): APJS.Texture {
    const easy = this.easyTextures, med = this.mediumTextures, hard = this.hardTextures;
    if (floor === 0) return easy[0];
    // After a narrow-top item, always give a wide one so the next drop is still fair.
    let tier = "easy";
    if (this.prevPickTier === "easy") {
      const r = Math.random();
      if (floor >= this.hardFromFloor && hard.length > 0 && r < 0.2) tier = "hard";
      else if (floor >= this.mediumFromFloor && med.length > 0 && r < 0.5) tier = "medium";
    }
    this.prevPickTier = tier;
    const list = tier === "hard" ? hard : tier === "medium" ? med : easy;
    return list[Math.floor(Math.random() * list.length)];
  }

  private spawnHeld(): void {
    if (this.poolIndex >= this.items.length) return;
    const it = this.items[this.poolIndex++];
    const tex = this.nextTex ? this.nextTex : this.easyTextures[0];
    if (this.prevPickTier === "") this.prevPickTier = "easy";
    const tw = tex.getWidth() > 0 ? tex.getWidth() : 400;
    const th = tex.getHeight() > 0 ? tex.getHeight() : 250;
    it.w = tw * this.itemScale;
    it.h = th * this.itemScale;
    it.img.texture = tex;
    it.st.sizeDelta = new APJS.Vector2f(it.w, it.h);
    it.col.size = new APJS.Vector2f(it.w / this.PPU, it.h / this.PPU);
    it.rb.static = true;
    it.rb.useGravity = false;
    it.rb.freezeX = false;
    it.rb.freezeZ = false;
    it.rb.velocity = new APJS.Vector2f(0, 0);
    it.rb.angularVelocity = 0;
    it.rb.rotation = 0;
    it.st.rotation = 0;
    it.obj.setEnabledInHierarchy(true);
    this.held = it;
    this.heldAnim = 0;
    this.nextTex = this.pickTexture(this.score + 1);
    this.setNextThumb();
    this.updateHeld(0);
  }

  private updateHeld(dt: number): void {
    const it = this.held;
    if (!it) return;
    this.heldAnim = Math.min(1, this.heldAnim + dt / 0.3);
    const k = 1 - Math.pow(1 - this.heldAnim, 3);
    const topY = this.clawBaseY + 100.5 - this.heldTopOffset + (1 - k) * 420;
    this.placeItem(it, this.clawX, topY - it.h / 2);
  }

  private drop(): void {
    const it = this.held;
    if (!it || this.heldAnim < 1) return;
    it.rb.velocity = new APJS.Vector2f(0, 0);
    it.rb.freezeX = true;   // falls straight down and stays where it lands
    it.rb.freezeZ = true;   // no wobble / random tipping while falling
    it.rb.gravityScale = this.fallGravityScale;
    it.rb.static = false;
    it.rb.useGravity = true;
    this.held = undefined;
    this.falling = it;
    this.lowFrames = 0;
    this.state = "DROPPING";
  }

  private updateFalling(): void {
    const it = this.falling;
    if (!it) return;
    const p = it.rb.position;
    it.x = p.x * this.PPU;
    it.y = p.y * this.PPU;
    if (it.y < -900) { this.showResult(false, "Rơi ra ngoài rồi!"); return; }
    const v = it.rb.velocity;
    if (v.x * v.x + v.y * v.y < this.settleSpeed * this.settleSpeed) this.lowFrames++;
    else this.lowFrames = 0;
    if (this.lowFrames >= this.settleFrames) this.onLanded(it);
  }

  private onLanded(it: TowerItem): void {
    const prev = this.tower.length > 0 ? this.tower[this.tower.length - 1] : undefined;
    if (prev && it.y <= prev.y) { this.showResult(false, "Rơi lệch khỏi tháp!"); return; }
    if (prev && !this.landingOk(it, prev)) { this.topple(it, it.x < prev.x ? -1 : 1); return; }

    it.rb.velocity = new APJS.Vector2f(0, 0);
    it.rb.useGravity = false;
    it.rb.static = true;
    this.placeItem(it, it.x, it.y);
    this.tower.push(it);
    this.falling = undefined;
    this.score++;
    this.towerTop = Math.max(this.towerTop, it.y + it.h / 2);
    const perfect = prev !== undefined && Math.abs(it.x - prev.x) < this.perfectPx;
    this.showPopup(perfect ? "HOÀN HẢO!" : "+1", it.x, it.y + it.h / 2 + 40);
    this.updateHud();
    if (this.score >= this.winFloors) { this.showResult(true, "Xếp đủ " + this.winFloors + " tầng!"); return; }
    this.spawnHeld();
    this.state = "AIMING";
  }

  // >= minOverlap of the upper item's width must rest on the lower item; a wider
  // item must also keep its center over the lower one or it looks impossible.
  private landingOk(up: TowerItem, low: TowerItem): boolean {
    const overlap = Math.min(up.x + up.w / 2, low.x + low.w / 2) - Math.max(up.x - up.w / 2, low.x - low.w / 2);
    if (overlap / up.w < this.minOverlap) return false;
    if (up.w > low.w && Math.abs(up.x - low.x) > low.w / 2) return false;
    return true;
  }

  private topple(it: TowerItem, dir: number): void {
    it.rb.freezeX = false;
    it.rb.freezeZ = false;
    it.rb.angularVelocity = -dir * 3;
    it.rb.velocity = new APJS.Vector2f(dir * 2.5, 0);
    this.showPopup("Lệch rồi!", it.x, it.y + it.h / 2 + 40);
    this.toppleTime = 0;
    this.state = "TOPPLING";
  }

  // Keep the drop gap visible: slide the tower + ground down as it grows.
  private updateScroll(dt: number): void {
    const over = this.towerTop - this.keepTopY; // towerTop is in screen space
    if (over < 0.5) return;
    const step = over * Math.min(1, dt * 4);
    this.towerTop -= step;
    for (const it of this.tower) this.placeItem(it, it.x, it.y - step);
    this.setGroundY(this.groundSt.anchoredPosition.y - step);
  }

  private placeItem(it: TowerItem, x: number, y: number): void {
    it.x = x;
    it.y = y;
    it.st.anchoredPosition = new APJS.Vector2f(x, y);
    it.rb.position = new APJS.Vector2f(x / this.PPU, y / this.PPU);
  }

  private parkItem(it: TowerItem): void {
    it.rb.static = true;
    it.rb.useGravity = false;
    it.rb.freezeX = false;
    it.rb.freezeZ = false;
    it.rb.velocity = new APJS.Vector2f(0, 0);
    it.rb.angularVelocity = 0;
    it.rb.rotation = 0;
    it.st.rotation = 0;
    this.placeItem(it, 0, -1400);
    it.obj.setEnabledInHierarchy(false);
  }

  private setGroundY(y: number): void {
    this.groundSt.anchoredPosition = new APJS.Vector2f(this.groundSt.anchoredPosition.x, y);
    if (this.groundRb) this.groundRb.position = new APJS.Vector2f(this.groundSt.anchoredPosition.x / this.PPU, y / this.PPU);
  }

  // ---------- UI ----------
  private setNextThumb(): void {
    if (this.nextImg && this.nextTex) this.nextImg.texture = this.nextTex;
  }

  private updateHud(): void {
    setText(this.scoreText, this.score + "/" + this.winFloors);
    setText(this.timerText, String(Math.ceil(this.timeLeft)));
  }

  private showPopup(msg: string, x: number, y: number): void {
    if (!this.popupText || !this.popupSt) return;
    setText(this.popupText, msg);
    this.popupY = y;
    this.popupSt.anchoredPosition = new APJS.Vector2f(clamp(x, -200, 140), y);
    this.popupTime = 0.9;
    this.popupText.setEnabledInHierarchy(true);
  }

  private updatePopup(dt: number): void {
    if (this.popupTime <= 0 || !this.popupSt) return;
    this.popupTime -= dt;
    this.popupY += 80 * dt;
    this.popupSt.anchoredPosition = new APJS.Vector2f(this.popupSt.anchoredPosition.x, this.popupY);
    if (this.popupTime <= 0) this.hidePopup();
  }

  private hidePopup(): void {
    this.popupTime = 0;
    if (this.popupText) this.popupText.setEnabledInHierarchy(false);
  }

  private showResult(win: boolean, reason: string): void {
    this.state = "RESULT";
    this.resultTime = 0;
    this.held = undefined;
    setText(this.resultTitle, win ? "THÀNH CÔNG!" : (reason === "Hết giờ rồi!" ? "HẾT GIỜ!" : "THÁP ĐỔ RỒI!"));
    setText(this.resultReason, reason);
    setText(this.resultScore, this.score + "/" + this.winFloors);
    if (this.resultOverlay) this.resultOverlay.setEnabledInHierarchy(true);
    this.hidePopup();
  }

}

class TowerItem {
  obj!: APJS.SceneObject;
  st!: APJS.ScreenTransform;
  rb!: APJS.RigidBody2D;
  col!: APJS.BoxCollider2D;
  img!: APJS.Image;
  w: number = 0;
  h: number = 0;
  x: number = 0;
  y: number = 0;
}

function clamp(v: number, a: number, b: number): number {
  return Math.max(a, Math.min(b, v));
}

function setText(obj: APJS.SceneObject, value: string): void {
  if (!obj) return;
  const t = obj.getComponent("Text") as APJS.Text;
  if (t) t.text = value;
}
